import os, re, sys

root = os.path.join(os.getcwd(), 'snapshots/s06')
cb_names = {}
ref_pats = [
    (re.compile(r'timer_setup\s*\(\s*[^,]+,\s*([A-Za-z_]\w*)\s*,'), 'timer_setup'),
    (re.compile(r'setup_timer\s*\(\s*[^,]+,\s*([A-Za-z_]\w*)\s*,'), 'setup_timer'),
    (re.compile(r'DEFINE_TIMER\s*\(\s*[^,]+,\s*([A-Za-z_]\w*)\s*,'), 'DEFINE_TIMER'),
    (re.compile(r'\.function\s*=\s*([A-Za-z_]\w*)\s*[,;)]'), 'function='),
]
files = []
for dirpath, dirs, fs in os.walk(root):
    for f in fs:
        if f.endswith(('.c', '.h')):
            files.append(os.path.join(dirpath, f))
texts = {}
for p in files:
    try:
        texts[p] = open(p, encoding='utf-8', errors='replace').read()
    except Exception:
        pass
for p, t in texts.items():
    for pat, kind in ref_pats:
        for m in pat.finditer(t):
            cb_names.setdefault(m.group(1), set()).add((os.path.relpath(p, root), kind, t[:m.start()].count('\n')+1))
print("CB_COUNT", len(cb_names))

lockre = re.compile(r'\bspin_lock\s*(?:_nested)?\s*\(\s*&')
results = []
def find_body(t, name):
    out = []
    for m in re.finditer(r'[\n\s](' + re.escape(name) + r')\s*\(', t):
        i = t.find('{', m.end())
        if i == -1 or i - m.end() > 600:
            continue
        # ensure this is a definition-ish site: previous non-space char should be start/end typical
        depth = 0; j = i
        while j < len(t):
            c = t[j]
            if c == '{': depth += 1
            elif c == '}':
                depth -= 1
                if depth == 0:
                    break
            j += 1
        out.append((m.start(), t[i:j]))
    return out

for name, regs in cb_names.items():
    if len(name) < 4:
        continue
    for p, t in texts.items():
        for (pos, body) in find_body(t, name):
            for lm in lockre.finditer(body):
                line = t[:pos + lm.start()].count('\n') + 1
                snippet = body[lm.start():body.find(')', lm.start())+1]
                results.append((os.path.relpath(p, root), name, line, snippet, sorted(regs)[:1]))
for r in sorted(set(results)):
    print("|".join(str(x) for x in r))
print("TOTAL_HITS", len(set(results)))
